class Crate {
  constructor(length, width, height) {
    if (![length, width, height].every(value => Number.isFinite(value) && value > 0)) {
      throw new TypeError('dimensions must be finite positive numbers');
    }
    this.length = length;
    this.width = width;
    this.height = height;
  }

  volume() {
    return this.length * this.width * this.height;
  }

  surfaceArea() {
    return 2 * (this.length * this.width + this.length * this.height + this.width + this.height);
  }
}

function EqualCrate(side) {
  return Reflect.construct(Crate, [side, side, side], new.target);
}

const equalCratePrototype = Object.create(Crate.prototype);
EqualCrate.prototype = new Proxy(equalCratePrototype, {
  get(target, property, receiver) {
    if (receiver === EqualCrate.prototype && (property === 'volume' || property === 'surfaceArea')) {
      return undefined;
    }
    return Reflect.get(target, property, receiver);
  }
});

module.exports = { Crate, EqualCrate };

