'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['Crate', 'EqualCrate']);
const { Crate, EqualCrate } = api;

const crate = new Crate(2, 3, 4);
assert.deepEqual({ length: crate.length, width: crate.width, height: crate.height }, { length: 2, width: 3, height: 4 });
for (const key of ['length', 'width', 'height']) assert.equal(Object.prototype.hasOwnProperty.call(crate, key), true);
assert.equal(crate.volume(), 24);
assert.equal(crate.surfaceArea(), 52);

const fractional = new Crate(0.5, 1.5, 2.5);
assert.equal(fractional.volume(), 1.875);
assert.equal(fractional.surfaceArea(), 11.5);

const equal = new EqualCrate(3);
assert.equal(equal instanceof EqualCrate, true);
assert.equal(equal instanceof Crate, true);
assert.deepEqual({ length: equal.length, width: equal.width, height: equal.height }, { length: 3, width: 3, height: 3 });
assert.equal(equal.volume(), 27);
assert.equal(equal.surfaceArea(), 54);
assert.strictEqual(EqualCrate.prototype.volume, undefined);
assert.strictEqual(EqualCrate.prototype.surfaceArea, undefined);
assert.strictEqual(equal.volume, Crate.prototype.volume);
assert.strictEqual(equal.surfaceArea, Crate.prototype.surfaceArea);

for (const args of [[0, 1, 1], [-1, 1, 1], [1, NaN, 1], [1, 1, Infinity], ['2', 3, 4], [1, null, 1]]) {
  assert.throws(() => new Crate(...args), TypeError);
}
for (const side of [0, -1, NaN, Infinity, '2']) assert.throws(() => new EqualCrate(side), TypeError);

